changeSet.sql:
CREATE TABLE review_sweep_schedule ( id UUID PRIMARY KEY, version BIGINT NOT NULL DEFAULT 0, workspace_id BIGINT NOT NULL, artifact_kind VARCHAR(64) NOT NULL, cadence VARCHAR(16) NOT NULL, lookback_days INTEGER NOT NULL, enabled BOOLEAN NOT NULL DEFAULT TRUE, next_run_at TIMESTAMPTZ NOT NULL, -- When a campaign was last actually opened, not when the schedule last came due. It -- anchors the next window, so a tick that looked at nothing must not move it. last_run_at TIMESTAMPTZ, created_by_account_id BIGINT NOT NULL, created_at TIMESTAMPTZ NOT NULL, updated_at TIMESTAMPTZ NOT NULL, CONSTRAINT fk_review_sweep_schedule_workspace FOREIGN KEY (workspace_id) REFERENCES workspace (id) ON DELETE CASCADE, CONSTRAINT ck_review_sweep_schedule_cadence CHECK (cadence IN ('DAILY','WEEKLY')), CONSTRAINT ck_review_sweep_schedule_kind CHECK (artifact_kind ~ '^[a-z][a-z0-9_]*\.[a-z][a-z0-9_]*$' AND length(artifact_kind) <= 64), -- The rule that keeps a sweep admissible as a live measurement, written where it cannot -- be bypassed: at most twice the cadence, never more than a week. Longer than that and -- the corpus was chosen with hindsight, which is a backfill campaign and records itself -- as one. Expressed as a CASE rather than a flat "<= 7" so the cadence half of the rule -- survives someone widening the cap. CONSTRAINT ck_review_sweep_schedule_lookback CHECK (lookback_days >= 1 AND lookback_days <= CASE cadence WHEN 'DAILY' THEN 2 WHEN 'WEEKLY' THEN 7 END) );
-- One schedule per kind of work per workspace. Two would each read the other's ledger rows -- as already covered, and only one could ever hold the workspace's single active campaign -- slot, so the loser would look enabled for ever while sweeping nothing. ALTER TABLE review_sweep_schedule ADD CONSTRAINT uq_review_sweep_schedule_workspace_kind UNIQUE (workspace_id, artifact_kind);
CREATE INDEX idx_review_sweep_schedule_due ON review_sweep_schedule (enabled, next_run_at);

-- Apart from EVENT although both measure the population events measure: this column answers
-- "did the provider tell us", and a sustained gap between what a sweep finds and what
-- arrived live is precisely the delivery failure the schedule exists to expose.
ALTER TABLE artifact_signal DROP CONSTRAINT IF EXISTS ck_artifact_signal_discovered_via;
ALTER TABLE artifact_signal ADD CONSTRAINT ck_artifact_signal_discovered_via
    CHECK (discovered_via IN ('EVENT','SYNC','MANUAL','BACKFILL','SWEEP'));

changeSet.rollback:
-- Same reasoning as the BACKFILL widening: narrowing the vocabulary makes these rows
-- unrepresentable, and deleting one returns its occurrence to "never seen", which without
-- the sweep that recorded it is the truth. The reviews it triggered keep their own rows.
DELETE FROM artifact_signal WHERE discovered_via = 'SWEEP';
ALTER TABLE artifact_signal DROP CONSTRAINT IF EXISTS ck_artifact_signal_discovered_via;
ALTER TABLE artifact_signal ADD CONSTRAINT ck_artifact_signal_discovered_via
    CHECK (discovered_via IN ('EVENT','SYNC','MANUAL','BACKFILL'));

changeSet.sql:
-- Existing rows are all hand-scoped campaigns; there was no other kind before this changeset. ALTER TABLE review_backfill_run ADD COLUMN discovered_via VARCHAR(16) NOT NULL DEFAULT 'BACKFILL';
-- Only these two. A campaign is never an event or a reconciliation, and a person asking about -- one artifact is not a campaign at all. ALTER TABLE review_backfill_run ADD CONSTRAINT ck_review_backfill_run_discovered_via CHECK (discovered_via IN ('BACKFILL','SWEEP'));
-- No foreign key on purpose. A constraint would force a choice between refusing to delete a -- schedule and nulling this column when one is deleted, and the second erases, from a row -- describing money that was spent, the record of what authorised spending it. ALTER TABLE review_backfill_run ADD COLUMN sweep_schedule_id UUID;
CREATE INDEX idx_review_backfill_run_sweep_schedule ON review_backfill_run (sweep_schedule_id) WHERE sweep_schedule_id IS NOT NULL;
-- A sweep's run is confirmed the moment it is created, by the account that created the -- schedule; there is no state in which one waits for a click. ALTER TABLE review_backfill_run ADD CONSTRAINT ck_review_backfill_run_sweep_confirmed CHECK (discovered_via <> 'SWEEP' OR (sweep_schedule_id IS NOT NULL AND confirmed_by_account_id IS NOT NULL));

changeSet.rollback:
ALTER TABLE review_backfill_run DROP CONSTRAINT IF EXISTS ck_review_backfill_run_sweep_confirmed;
DROP INDEX IF EXISTS idx_review_backfill_run_sweep_schedule;
ALTER TABLE review_backfill_run DROP COLUMN IF EXISTS sweep_schedule_id;
ALTER TABLE review_backfill_run DROP CONSTRAINT IF EXISTS ck_review_backfill_run_discovered_via;
ALTER TABLE review_backfill_run DROP COLUMN IF EXISTS discovered_via;

