    IF EXISTS (SELECT 1 FROM config_audit_event WHERE entity_type = 'REVIEW_SWEEP_SCHEDULE') THEN
        RAISE WARNING 'The audit entity-type constraint remains widened because append-only history contains REVIEW_SWEEP_SCHEDULE rows';
        RETURN;
