    CHECK (pause_reason IS NULL OR pause_reason IN
        ('BUDGET_EXHAUSTED','BINDING_DISABLED','WORKSPACE_UNAVAILABLE'));

changeSet.sql:
/* The dedup key is (workspace, kind, artifact, signal_name, revision), and a manual request
   takes a fresh run id as its revision, so no row can already hold the new name for the same
   revision. The NOT EXISTS guard is there so that if one somehow does, the migration leaves
   it where it is instead of failing the deploy or deleting somebody's history. */
UPDATE artifact_signal old
   SET signal_name = replace(old.signal_name, 'review_requested', 'manual_review')
 WHERE old.signal_name IN ('scm.pull_request.review_requested', 'scm.issue.review_requested')
   AND NOT EXISTS (
       SELECT 1 FROM artifact_signal fresh
        WHERE fresh.workspace_id = old.workspace_id
          AND fresh.artifact_kind = old.artifact_kind
          AND fresh.artifact_id = old.artifact_id
          AND fresh.revision = old.revision
          AND fresh.signal_name = replace(old.signal_name, 'review_requested', 'manual_review')
   );

/* A workspace may have authored a practice bound to the old name: the signal picker offers
   every signal a kind declares, the manual one included. The name is a quoted string inside
   the bindings array, and no other value in that document contains it — a source kind spells
   the same domain with hyphens — so a text substitution is exact here. */
UPDATE practice SET bindings = replace(bindings::text,
        'review_requested"', 'manual_review"')::jsonb
    WHERE bindings::text LIKE '%.review_requested"%';

UPDATE curated_practice_override SET bindings = replace(bindings::text,
        'review_requested"', 'manual_review"')::jsonb
    WHERE bindings::text LIKE '%.review_requested"%';

/* A revision is immutable by trigger, and the practice's current revision must project the
   practice exactly. Renaming one side and not the other would leave the projection broken,
   so the revision moves with it under the same suspension the earlier bindings migration
   used, and both land inside this changeset's transaction before the deferred projection
   check runs. */
ALTER TABLE practice_revision DISABLE TRIGGER practice_revision_immutable_update;
UPDATE practice_revision SET bindings = replace(bindings::text,
        'review_requested"', 'manual_review"')::jsonb
    WHERE bindings::text LIKE '%.review_requested"%';
/* The signal name feeds the review-rule fingerprint, so any revision that moved now carries
   one describing a rule set spelled a way that no longer exists. Cleared for
   CatalogProvenanceBackfill to recompute on the next boot, as changesets -21, -22 and -25 do. */
UPDATE practice_revision SET review_rule_fingerprint = NULL
    WHERE bindings::text LIKE '%.manual_review"%';
ALTER TABLE practice_revision ENABLE TRIGGER practice_revision_immutable_update;

rollback.sql:
