   SET signal_name = replace(old.signal_name, 'manual_review', 'review_requested')
 WHERE old.signal_name IN ('scm.pull_request.manual_review', 'scm.issue.manual_review')
   AND NOT EXISTS (
       SELECT 1 FROM artifact_signal stale
        WHERE stale.workspace_id = old.workspace_id
          AND stale.artifact_kind = old.artifact_kind
          AND stale.artifact_id = old.artifact_id
          AND stale.revision = old.revision
          AND stale.signal_name = replace(old.signal_name, 'manual_review', 'review_requested')
   );

UPDATE practice SET bindings = replace(bindings::text,
        'manual_review"', 'review_requested"')::jsonb
    WHERE bindings::text LIKE '%.manual_review"%';

