        'manual_review"', 'review_requested"')::jsonb
    WHERE bindings::text LIKE '%.manual_review"%';
UPDATE practice_revision SET review_rule_fingerprint = NULL
    WHERE bindings::text LIKE '%.review_requested"%';
ALTER TABLE practice_revision ENABLE TRIGGER practice_revision_immutable_update;

changeSet.sql:
-- The column could not say "I have not decided". Every practice therefore shipped holding an -- opinion nobody expressed -- the loudest one -- and turning the system down meant editing every -- row by hand. At forty practices that is tedious, at a hundred across twenty-five areas nobody -- does it, so the shipped default was the only configuration that ever ran. NULL is the fix: it -- is the difference between a decision and the absence of one, and it lets one decision at the -- area or the workspace cover everything below it that has not disagreed. ALTER TABLE practice DROP CONSTRAINT IF EXISTS chk_practice_review_tier; ALTER TABLE practice ALTER COLUMN review_tier DROP DEFAULT; ALTER TABLE practice ALTER COLUMN review_tier DROP NOT NULL;
-- OFF and MEASURE carry over exactly: not reviewed, and reviewed-but-silent, are unchanged acts. -- ENGAGE carries over exactly as DELIVER: feedback sent without anyone approving it. -- -- COACH is the one that cannot be preserved, and it goes to the QUIETER side. It meant "reviewed, -- and raised in the mentor conversation but never on the work" -- one claim about autonomy and one -- about reach. Reach is now a single workspace setting, so a per-practice COACH has nowhere to be -- stored. Sending it to DELIVER would preserve its reach only by granting it autonomy it never -- had, and on a workspace reaching the work it would start commenting on people's changes because -- of a migration. OBSERVE keeps every observation COACH was recording and says nothing until a -- person decides otherwise. A system that comments on somebody's work gets louder by an explicit -- decision, never by an upgrade. UPDATE practice SET review_tier = CASE review_tier WHEN 'MEASURE' THEN 'OBSERVE' WHEN 'COACH' THEN 'OBSERVE' WHEN 'ENGAGE' THEN 'DELIVER' ELSE review_tier END;
-- PROPOSE is admitted here and refused at every write boundary until an approval queue exists. -- Admitting it now costs nothing and means the value is already representable when it ships; -- a column that had to be widened later would be a migration on the day of the feature. ALTER TABLE practice ADD CONSTRAINT chk_practice_review_tier CHECK (review_tier IS NULL OR review_tier IN ('OFF', 'OBSERVE', 'PROPOSE', 'DELIVER'));
-- The workspace default is left unset by this migration, and an unset default resolves to -- DELIVER -- exactly what every one of these rows already did. So a practice sitting at the -- migrated default is a practice with no opinion, and saying so changes no behaviour at all -- while turning forty edits into one. A practice at OFF or OBSERVE disagreed on purpose and -- keeps its explicit value. UPDATE practice SET review_tier = NULL WHERE review_tier = 'DELIVER';

changeSet.rollback:
-- Rolling back has to re-fill the NULLs, because the old column was NOT NULL. They become
-- ENGAGE: that is what an unset tier resolved to going forward, so the schema before and after
-- this rollback describe the same behaviour.
ALTER TABLE practice DROP CONSTRAINT IF EXISTS chk_practice_review_tier;
UPDATE practice SET review_tier = 'ENGAGE' WHERE review_tier IS NULL;
UPDATE practice SET review_tier = CASE review_tier
    WHEN 'OBSERVE' THEN 'MEASURE'
    WHEN 'DELIVER' THEN 'ENGAGE'
    WHEN 'PROPOSE' THEN 'MEASURE'
    ELSE review_tier
END;
ALTER TABLE practice ALTER COLUMN review_tier SET NOT NULL;
ALTER TABLE practice ALTER COLUMN review_tier SET DEFAULT 'ENGAGE';
ALTER TABLE practice ADD CONSTRAINT chk_practice_review_tier
    CHECK (review_tier IN ('OFF', 'MEASURE', 'COACH', 'ENGAGE'));

ALTER TABLE workspace DROP CONSTRAINT IF EXISTS chk_workspace_feedback_reach;
ALTER TABLE workspace DROP CONSTRAINT IF EXISTS chk_workspace_default_review_tier;
ALTER TABLE workspace DROP COLUMN IF EXISTS practice_feedback_reach;
ALTER TABLE workspace DROP COLUMN IF EXISTS practice_default_review_tier;

changeSet.sql:
-- Same value, ordinary English. The evidence is that the old name was never reached: the -- orchestrator asks for it in twenty places and live data holds none of it, while a large share -- of the NOT_APPLICABLE rows are phrased as could-not-tell in their own reasoning -- a detector -- saying the right thing under the wrong label, which enters a person's record as "nothing to -- see here" on a change where there was something to see. A word a model reaches for is not a -- cosmetic concern when the whole value exists to be reached for. ALTER TABLE observation DROP CONSTRAINT IF EXISTS chk_observation_presence_assessment; ALTER TABLE observation DROP CONSTRAINT IF EXISTS chk_observation_presence;
UPDATE observation SET presence = 'INCONCLUSIVE' WHERE presence = 'INDETERMINATE';
ALTER TABLE observation ADD CONSTRAINT chk_observation_presence CHECK (presence IN ('PRESENT', 'ABSENT', 'NOT_APPLICABLE', 'INCONCLUSIVE')); -- The coupling is unchanged: assessment is present exactly when the presence carries a -- direction. INCONCLUSIVE stays on the null side with NOT_APPLICABLE, which is the whole point -- of the value -- a run that could not settle the question must not smuggle a verdict out with it. ALTER TABLE observation ADD CONSTRAINT chk_observation_presence_assessment CHECK ((presence IN ('NOT_APPLICABLE', 'INCONCLUSIVE') AND assessment IS NULL) OR (presence IN ('PRESENT', 'ABSENT') AND assessment IS NOT NULL));

changeSet.rollback:
ALTER TABLE observation DROP CONSTRAINT IF EXISTS chk_observation_presence_assessment;
ALTER TABLE observation DROP CONSTRAINT IF EXISTS chk_observation_presence;
UPDATE observation SET presence = 'INDETERMINATE' WHERE presence = 'INCONCLUSIVE';
ALTER TABLE observation ADD CONSTRAINT chk_observation_presence
    CHECK (presence IN ('PRESENT', 'ABSENT', 'NOT_APPLICABLE', 'INDETERMINATE'));
ALTER TABLE observation ADD CONSTRAINT chk_observation_presence_assessment
    CHECK ((presence IN ('NOT_APPLICABLE', 'INDETERMINATE') AND assessment IS NULL)
        OR (presence IN ('PRESENT', 'ABSENT') AND assessment IS NOT NULL));

changeSet.sql:
-- The axis is how much the system does without you, and OBSERVE and PROPOSE both sat at "runs,
-- records, sends nothing". They were meant to differ over whether feedback had been prepared for
-- someone to approve, but nothing on the delivery path ever prepared it: findings are dropped
-- before a body is composed, and the withheld ledger row carries no body. So the boundary was
-- invisible on every screen that showed it, which is the same fault that made COACH and ENGAGE
-- unpickable. One middle rung carries the whole of "reviewed, recorded, silent".
--
-- PROPOSE is the survivor rather than OBSERVE because the rung has to stay selectable once the
-- approval queue exists, and a column that had to be re-mapped on the day of that feature would
-- be a migration nobody wants to run then. Behaviour is identical either way: neither tier
-- delivers, so no workspace gets louder or quieter here.
UPDATE practice SET review_tier = 'PROPOSE' WHERE review_tier = 'OBSERVE';
ALTER TABLE practice DROP CONSTRAINT IF EXISTS chk_practice_review_tier;
ALTER TABLE practice ADD CONSTRAINT chk_practice_review_tier
    CHECK (review_tier IS NULL OR review_tier IN ('OFF', 'PROPOSE', 'DELIVER'));

UPDATE practice_area SET review_tier = 'PROPOSE' WHERE review_tier = 'OBSERVE';
ALTER TABLE practice_area DROP CONSTRAINT IF EXISTS chk_practice_area_review_tier;
ALTER TABLE practice_area ADD CONSTRAINT chk_practice_area_review_tier
    CHECK (review_tier IS NULL OR review_tier IN ('OFF', 'PROPOSE', 'DELIVER'));

-- NULL still means "this workspace has never chosen", and still resolves to DELIVER. Only the
-- admitted vocabulary narrows.
UPDATE workspace SET practice_default_review_tier = 'PROPOSE'
    WHERE practice_default_review_tier = 'OBSERVE';
ALTER TABLE workspace DROP CONSTRAINT IF EXISTS chk_workspace_default_review_tier;
ALTER TABLE workspace ADD CONSTRAINT chk_workspace_default_review_tier
    CHECK (practice_default_review_tier IS NULL
        OR practice_default_review_tier IN ('OFF', 'PROPOSE', 'DELIVER'));

changeSet.rollback:
-- PROPOSE maps back to OBSERVE without ambiguity. Until this changeset, PROPOSE was refused at
-- every write boundary and no code path could store it, so every PROPOSE row in a database this
-- rollback can reach was written by the UPDATE above.
ALTER TABLE practice DROP CONSTRAINT IF EXISTS chk_practice_review_tier;
ALTER TABLE practice_area DROP CONSTRAINT IF EXISTS chk_practice_area_review_tier;
ALTER TABLE workspace DROP CONSTRAINT IF EXISTS chk_workspace_default_review_tier;

UPDATE practice SET review_tier = 'OBSERVE' WHERE review_tier = 'PROPOSE';
UPDATE practice_area SET review_tier = 'OBSERVE' WHERE review_tier = 'PROPOSE';
UPDATE workspace SET practice_default_review_tier = 'OBSERVE'
    WHERE practice_default_review_tier = 'PROPOSE';

ALTER TABLE practice ADD CONSTRAINT chk_practice_review_tier
    CHECK (review_tier IS NULL OR review_tier IN ('OFF', 'OBSERVE', 'PROPOSE', 'DELIVER'));
ALTER TABLE practice_area ADD CONSTRAINT chk_practice_area_review_tier
    CHECK (review_tier IS NULL OR review_tier IN ('OFF', 'OBSERVE', 'PROPOSE', 'DELIVER'));
ALTER TABLE workspace ADD CONSTRAINT chk_workspace_default_review_tier
    CHECK (practice_default_review_tier IS NULL
        OR practice_default_review_tier IN ('OFF', 'OBSERVE', 'PROPOSE', 'DELIVER'));

changeSet.sql:
-- Named before constrained. A bare check-constraint violation says which table refused and
-- nothing about which rows, and these four columns are old enough to hold a spelling from a
-- vocabulary that predates the grammar. The operator decides what happens to that data; a
-- migration that quietly rewrote or deleted it would be deciding for them.
DO $$
DECLARE offending text;
BEGIN
    SELECT string_agg(DISTINCT entry, ', ') INTO offending FROM (
        SELECT 'artifact_signal.artifact_kind=' || artifact_kind AS entry FROM artifact_signal
         WHERE artifact_kind !~ '^[a-z][a-z0-9_]*\.[a-z][a-z0-9_]*$' OR length(artifact_kind) > 64
        UNION ALL
        SELECT 'agent_job.artifact_kind=' || artifact_kind FROM agent_job
         WHERE artifact_kind IS NOT NULL
           AND (artifact_kind !~ '^[a-z][a-z0-9_]*\.[a-z][a-z0-9_]*$' OR length(artifact_kind) > 64)
        UNION ALL
        SELECT 'practice.applies_to=' || applies_to FROM practice
         WHERE applies_to !~ '^[a-z][a-z0-9_]*\.[a-z][a-z0-9_]*$' OR length(applies_to) > 64
        UNION ALL
        SELECT 'review_backfill_run.artifact_kind=' || artifact_kind FROM review_backfill_run
         WHERE artifact_kind !~ '^[a-z][a-z0-9_]*\.[a-z][a-z0-9_]*$' OR length(artifact_kind) > 64
    ) found;
    IF offending IS NOT NULL THEN
        RAISE EXCEPTION 'Cannot enforce the artifact-kind grammar: rows hold kinds outside it (%). Migrate those rows to <domain>.<kind> first — this changeset will not rewrite them for you.', offending;
    END IF;
END $$;

ALTER TABLE artifact_signal DROP CONSTRAINT IF EXISTS ck_artifact_signal_artifact_kind;
ALTER TABLE artifact_signal ADD CONSTRAINT ck_artifact_signal_artifact_kind
    CHECK (artifact_kind ~ '^[a-z][a-z0-9_]*\.[a-z][a-z0-9_]*$' AND length(artifact_kind) <= 64);

-- Nullable: a job row predating the discriminator carries no kind, and this changeset is not
-- the place that decides what one of those is about.
ALTER TABLE agent_job DROP CONSTRAINT IF EXISTS ck_agent_job_artifact_kind;
ALTER TABLE agent_job ADD CONSTRAINT ck_agent_job_artifact_kind
    CHECK (artifact_kind IS NULL
           OR (artifact_kind ~ '^[a-z][a-z0-9_]*\.[a-z][a-z0-9_]*$' AND length(artifact_kind) <= 64));

ALTER TABLE practice DROP CONSTRAINT IF EXISTS chk_practice_applies_to;
ALTER TABLE practice ADD CONSTRAINT chk_practice_applies_to
    CHECK (applies_to ~ '^[a-z][a-z0-9_]*\.[a-z][a-z0-9_]*$' AND length(applies_to) <= 64);

ALTER TABLE review_backfill_run DROP CONSTRAINT IF EXISTS ck_review_backfill_run_artifact_kind;
ALTER TABLE review_backfill_run ADD CONSTRAINT ck_review_backfill_run_artifact_kind
    CHECK (artifact_kind ~ '^[a-z][a-z0-9_]*\.[a-z][a-z0-9_]*$' AND length(artifact_kind) <= 64);

changeSet.rollback:
ALTER TABLE review_backfill_run DROP CONSTRAINT IF EXISTS ck_review_backfill_run_artifact_kind;
ALTER TABLE practice DROP CONSTRAINT IF EXISTS chk_practice_applies_to;
ALTER TABLE agent_job DROP CONSTRAINT IF EXISTS ck_agent_job_artifact_kind;
ALTER TABLE artifact_signal DROP CONSTRAINT IF EXISTS ck_artifact_signal_artifact_kind;

